// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {FlashGovernanceArbiter} from "../src/FlashGovernanceArbiter.sol";

contract InvMutTest is Test {
    FlashGovernanceArbiter c;
    address dao;

    function setUp() public {
        dao = address(new __InvMutHandleStub());
        c = new FlashGovernanceArbiter(dao);
    }

    function testFuzz_property(address actor, address target, address asset, uint256 amount, uint256 unlockTime) public {
        // Admissible, wide domain: nonzero amount so the pending record is "live".
        vm.assume(amount > 0);
        // Make the target be a governance-approved sender for the pending key.
        // We use setGoverned via prank from dao.
        address[] memory gov = new address[](1);
        bool[] memory flags = new bool[](1);
        gov[0] = target;
        flags[0] = true;
        vm.prank(dao);
        c.setGoverned(gov, flags);

        // Configure flash governance so assertGovernanceApproved can run.
        address[] memory dummy = new address[](0);
        bool[] memory dummyB = new bool[](0);
        vm.prank(dao);
        c.configureFlashGovernance(asset, amount, unlockTime, false);

        // Set the pending decision by having `target` (a governed sender) call
        // assertGovernanceApproved, which records pendingFlashDecision[address(c)][target].
        // We want the caller of withdrawGovernanceAsset to be `target` (the sender who
        // created the pending decision) with targetContract = address(c).
        vm.prank(dao);
        c.configureSecurityParameters(1, 0, 1);
        vm.prank(asset);
        // make the ERC20 transferFrom succeed via a permissive token
        // (asset is a fuzzed address; we deploy a permissive token helper instead)
        // -> handled below.
        // Instead, deploy a permissive token here for determinism of the transfer.
        address token = address(new __PermissiveToken());
        vm.prank(dao);
        c.configureFlashGovernance(token, amount, 1, false);

        // Now have target create the pending decision for address(c).
        vm.prank(target);
        c.assertGovernanceApproved(target, address(c), false);

        // Warp forward past the unlock time so a legitimate withdrawal is possible.
        vm.warp(block.timestamp + 2);

        // Caller (target) tries to withdraw; the reference will delete the pending
        // record on success, the bug's inverted guard reverts.
        vm.prank(target);
        try c.withdrawGovernanceAsset(address(c), token) {
            // success path
        } catch {}

        // General rule: after the call, the pending record for the caller must be
        // deleted (i.e., amount is zero) whenever the pre-call amount was nonzero.
        (uint256 pAmount, , , ) = c.pendingFlashDecision(address(c), target);
        assertTrue(pAmount == 0);
    }
}

